from ute_common_store.store import Store
from ute_common_converter.to_number import to_float

from .thread import run_in_thread


class ute_async(object):
    """
    Introduction
    ************


    Library to execute keyword asynchronously.


    Package requirements
    ********************


    * Python 2.7.x
    * setuptools >=2.1
    * pip >= 1.5
    * ute_installer >= 0.25


    Installation
    ************


    This section describes how to install **ute_async** as single library. For robotlte below steps are not needed.


    Installation for UTE test line
    ------------------------------


    ::

        pip install -U ute_async


    Installation for NON UTE test line
    ----------------------------------


    ::

        pip install -U -i http://pypi.ute.inside.nsn.com:25102 pip
        pip install -U -i http://pypi.ute.inside.nsn.com:25102 setuptools
        pip install -U -i http://pypi.ute.inside.nsn.com:25102 ute_installer
        pip install -U -i http://pypi.ute.inside.nsn.com:25102 ute_async


    Installation from SVN
    ---------------------


    ::

        pip install svn+https://ca_ute_test:utetest@svne1.access.nsn.com/isource/svnroot/utelibs/ute_async/trunk/#egg=ute_async


    Multiple instances
    ******************


    This library supports multiple setups where each can be specified by **alias** argument for every keyword.
    This argument can be specified as follow:
    ::

        Start async     OperatingSystem     List Directory         alias=async1
        Start async     BuiltIn             Sleep        10s       alias=async2


    Restrictions
    ************

    1. Asynchronous execution is not safe by default for all libraries. Each library needs to be check before execution because
       many libraries are not thread safe.

    2. No logging during execution.

    3. Results and exceptions are cached by library and evaluate via "Get async result" and "Wait for async result" keywords.

    4. Threads are executed in daemon mode (python will not wait for them in case of unexpected close) and some result data might be corrupted.
       Please ensure that every "Stop async" is always executed in "Teardown".


    Keywords
    ********
    """

    ROBOT_LIBRARY_SCOPE = 'TEST SUITE'

    def __init__(self):
        self.store = Store()

    def start_async(self, library_name, keyword_name, *args, **kwargs):
        """Starts keyword in separate thread.

        :param string library_name: Library from which keyword will be executed in separate thread.
        :param string keyword_name: Keyword name which will be executed in separate thread.

        :kwargs should be used to specify **use_alias_in_kw**:
            * **use_alias_in_kw (bool)     -Specify whether value of named argument 'alias' should be also passed to executed keyword defined
                                            in 'keyword_name' argument.

        :note: Parameters *args and **kwargs are supported and are passed to final keyword without modification(with exception of 'alias'
               named argument, if argument 'use_alias_in_kw' is set to False.
        :note: Library (in library_name) has to be imported before start_async keyword.
        """
        alias = kwargs.get('alias')
        if 'alias' in kwargs and not kwargs.get('use_alias_in_kw', False):
            del kwargs['alias']
        if 'use_alias_in_kw' in kwargs:
            del kwargs['use_alias_in_kw']
        thread = run_in_thread(library_name, keyword_name, *args, **kwargs)
        self.store.add(thread, alias)

    def get_async_result(self, **kwargs):
        """Gets execution result if exist.

        :return: Keyword execution result.
        """
        alias = kwargs.get('alias')
        thread = self.store.get(alias)
        return thread.result.get()

    def wait_for_async_result(self, timeout=0, **kwargs):
        """Waits for execution result.

        :param float timeout: Timeout for wait operation.

        :return: Keyword execution result.
        :raise: AsyncException in case of timeout.
        """
        alias = kwargs.get('alias')
        thread = self.store.get(alias)
        timeout = to_float(timeout)
        return thread.result.get(timeout=timeout)

    def stop_async(self, timeout=1, **kwargs):
        """Stops keyword running in separate thread.

        :param float timeout: Timeout for stop operation.
        """
        alias = kwargs.get('alias')
        timeout = to_float(timeout)
        thread = self.store.get(alias)
        thread.terminate_and_join(timeout)
        self.store.remove(alias)
